"""Supply consultation guidance and examples while preserving native tools."""

from typing import Final

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


GUIDANCE: Final[str] = """处理退款咨询，以本次日期、学员消息、客服工作规则、退款政策和订单记录为依据。
1. 确认并读取当次三份材料；路径明确就读取，不明确再定位。已取得完整内容直接使用，不因重复看到指引而重读或让学员重复提供。新咨询或材料更新须重新确认，不能只凭同名文件沿用旧内容。
2. 先按当次工作规则确定处理和回复要求，再结合订单、政策和日期判断；不套用其他机构的条件、比例、时限或话术，不补写未提供的业务事实。
3. 缺失、读取失败或实质冲突不视为已核实。按已知当次规则回复有依据的部分并作必要澄清，不编造金额、承诺或已完成操作。
4. 成稿先对照下方‘单条退款回复’案例：核算完整，对外从结论组成正文。写全当次要求的称呼、退法、实际应退金额、规定到账话术及适用的转人工、工单发送方式、未付分期处理等必需事项。未被当次要求、也不用于回应学员具体争议的订单标识、课程与日期复述、完整算式、触发词复述和客套话不默认加入；必要解释只写足以回应争议的部分。只发一条学员正文，不用 write_file、deliver_files 或 message 另发正文，不加完成报告。
5. 发送前分别核对整条文字的措辞和长度：当次全篇禁词也约束日期解释、天数纠正和消息复述，不仅约束到账句；改用不违禁且含义不变的表达，或省略非必需复述，到账仍用当次规定说法。再按当次计数口径核对实际要发的全部文字；超长先精简非必需内容，不能删必需信息。任何改动后重核措辞与长度，只发送已核对版本并结束，不附核对记录或再加尾句。"""

SKILL_NAME: Final[str] = "refund-single-reply"
SKILL_SOURCE: Final[str] = "curator-capability"


class RefundCapability(CapabilityStrategy):
    """Own one example skill and guidance; delegate native tool selection."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        text = request.assets["refund_single_reply.SKILL.md"]
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": text},
                source="refund-desk/single-reply-method",
            ),
        )

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        matches = [
            skill for skill in request.skills
            if skill.name == SKILL_NAME and skill.source == SKILL_SOURCE
        ]
        if len(matches) != 1 or not matches[0].available:
            raise ValueError(
                "Required skill curator-capability/refund-single-reply is missing, "
                "ambiguous or unavailable"
            )
        target = matches[0]
        selected = [SkillSelection(name=target.name, source=target.source, delivery="body")]
        identities = [(skill.source, skill.name) for skill in request.skills]
        for skill in request.skills:
            if not skill.available or (skill.source, skill.name) == (target.source, target.name):
                continue
            if identities.count((skill.source, skill.name)) != 1:
                raise ValueError(f"Ambiguous available skill: {skill.source}/{skill.name}")
            selected.append(SkillSelection(name=skill.name, source=skill.source, delivery="catalog"))
        return CapabilitySelection(tools=None, skills=tuple(selected), guidance=GUIDANCE)


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> RefundCapability:
    """Construct an inert owner, leaving task identity and checkpoint untouched."""
    return RefundCapability(registrar)
